CREATE POLICY "portal access required" ON public.listings AS RESTRICTIVE FOR ALL TO anon, authenticated USING (public.has_role(auth.uid(), 'user') OR public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'user') OR public.has_role(auth.uid(), 'admin'));
CREATE OR REPLACE FUNCTION public.validate_posting_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = NEW.owner_id) THEN RAISE EXCEPTION 'Create your profile before posting'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER require_posting_profile BEFORE INSERT ON public.listings FOR EACH ROW EXECUTE FUNCTION public.validate_posting_profile();
CREATE OR REPLACE FUNCTION public.validate_profile_device() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF TG_OP = 'INSERT' AND (NEW.device_id IS NULL OR length(trim(NEW.device_id)) = 0) THEN RAISE EXCEPTION 'A device identifier is required to create a profile'; END IF; IF TG_OP = 'UPDATE' AND NEW.device_id IS DISTINCT FROM OLD.device_id THEN RAISE EXCEPTION 'Profile device cannot be changed'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER protect_profile_device BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.validate_profile_device();